fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut result = vec![0; n]; // Create a new vector with the same length

    if n == 1 {
        // If there's only one element, return it as is
        result[0] = a[0];
    } else {
        // Swap the first and last elements
        result[0] = a[n - 1]; // Last element of input becomes first in result
        result[n - 1] = a[0]; // First element of input becomes last in result
        
        // Copy the interior elements
        for i in 1..(n - 1) {
            result[i] = a[i];
        }
    }

    result
}